import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

function validationFailure(
  validator: ValidateFunction,
  input: Record<string, unknown>,
  name: string
): ToolResponse | undefined {
  if (validator(input)) return undefined;

  const error = validator.errors?.[0] as Record<string, unknown> | undefined;
  const params = error?.params as Record<string, unknown> | undefined;
  const missingProperty = error?.keyword === 'required' ? params?.missingProperty : undefined;
  const instancePath = jsonPointerPath(error?.instancePath, error?.dataPath);
  const propertyPath =
    typeof missingProperty === 'string' ? `${instancePath}/${missingProperty}` : instancePath || 'input';
  const constraint =
    error?.keyword === 'required' ? 'is required' : (error?.message ?? 'is invalid').replace(/^should be\b/, 'must be');
  log.warn('tool', 'input validation failed', {name, propertyPath, constraint});
  return {result: `Invalid tool input: ${propertyPath} ${constraint}.`};
}

function jsonPointerPath(instancePath: unknown, dataPath: unknown): string {
  if (typeof instancePath === 'string') return instancePath;
  if (typeof dataPath !== 'string') return '';

  return dataPath.replace(
    /\[(\d+)\]|\.([^.[\]]+)/g,
    (_match, index: string | undefined, property: string | undefined) => {
      const segment = index ?? property ?? '';
      return `/${segment.replace(/~/g, '~0').replace(/\//g, '~1')}`;
    }
  );
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly schemaValidator = new Ajv({strict: false, validateFormats: false} as ConstructorParameters<
    typeof Ajv
  >[0]);
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.schemaValidator.compile(definition.inputSchema);
      } catch (error) {
        throw new Error(`Invalid input schema for tool ${resolved.name}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  private validatorFor(tool: StoredTool): ValidateFunction {
    if (tool.validator) return tool.validator;
    const definition = this.resolveDefinition(tool.definitionSource);
    const cached = this.dynamicValidators.get(definition.inputSchema);
    if (cached) return cached;
    const validator = this.schemaValidator.compile(definition.inputSchema);
    this.dynamicValidators.set(definition.inputSchema, validator);
    return validator;
  }

  /** Returns schema rejections as tool results; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rejection = validationFailure(this.validatorFor(tool), input, name);
    if (rejection) return rejection;
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import Ajv, {type ValidateFunction} from 'ajv';
import {jest} from '@jest/globals';
import {type ToolExecutor, ToolRegistry} from './registry.js';

function registerWeather(registry: ToolRegistry, executor: ToolExecutor): void {
  registry.register(weatherDefinition(), executor);
}

function weatherDefinition() {
  return {
    name: 'get_weather',
    description: 'Gets weather for a location',
    inputSchema: {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    },
  };
}

function nestedWeatherDefinition() {
  return {
    name: 'get_weather',
    description: 'Gets weather for a location',
    inputSchema: {
      type: 'object',
      properties: {
        forecast: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      required: ['forecast'],
    },
  };
}

function callCount(executor: jest.Mock<ToolExecutor>): number {
  const {calls} = executor.mock;
  return calls.length;
}

function weatherExecutor(): jest.Mock<ToolExecutor> {
  return jest.fn(async () => 'sunny');
}

describe('ToolRegistry', () => {
  it('returns a rejection for missing required input without calling the executor', async () => {
    const registry = new ToolRegistry();
    const executor = weatherExecutor();
    registerWeather(registry, executor);

    const response = await registry.execute('get_weather', {});

    expect({result: response.result, executorCalls: callCount(executor)}).toEqual({
      result: expect.stringMatching(/location.*required|required.*location/i),
      executorCalls: 0,
    });
  });

  it('names the full path for a nested missing required input field', async () => {
    const registry = new ToolRegistry();
    const executor = weatherExecutor();
    registry.register(nestedWeatherDefinition(), executor);

    const response = await registry.execute('get_weather', {forecast: {}});

    expect({result: response.result, executorCalls: callCount(executor)}).toEqual({
      result: expect.stringMatching(/forecast\/location.*required/i),
      executorCalls: 0,
    });
  });

  it('names the full path for a nested wrong-typed input field', async () => {
    const registry = new ToolRegistry();
    const executor = weatherExecutor();
    registry.register(nestedWeatherDefinition(), executor);

    const response = await registry.execute('get_weather', {forecast: {location: 8675309}});

    expect({result: response.result, executorCalls: callCount(executor)}).toEqual({
      result: 'Invalid tool input: /forecast/location must be string.',
      executorCalls: 0,
    });
  });

  it('names the path and expected type for wrong-typed input without leaking its value', async () => {
    const registry = new ToolRegistry();
    const executor = weatherExecutor();
    registerWeather(registry, executor);

    const response = await registry.execute('get_weather', {location: 8675309});

    expect({
      result: response.result,
      executorCalls: callCount(executor),
      leaksValue: response.result.includes('8675309'),
    }).toEqual({
      result: expect.stringMatching(/location.*string/i),
      executorCalls: 0,
      leaksValue: false,
    });
  });

  it('normalizes Ajv should-be wording for a rejected input type', async () => {
    const validate = jest.fn(() => false) as unknown as ValidateFunction;
    validate.errors = [{instancePath: '/location', keyword: 'type', message: 'should be string'}];
    const compile = jest.spyOn(Ajv.prototype, 'compile').mockReturnValue(validate);
    const registry = new ToolRegistry();
    const executor = weatherExecutor();
    registerWeather(registry, executor);

    const response = await registry.execute('get_weather', {location: 8675309});

    expect(response.result).toBe('Invalid tool input: /location must be string.');
    compile.mockRestore();
  });

  it('names the path and enum constraint for an input outside the declared enum', async () => {
    const registry = new ToolRegistry();
    const executor = weatherExecutor();
    registry.register(
      {
        name: 'get_weather',
        description: 'Gets weather for a location',
        inputSchema: {
          type: 'object',
          properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}},
          required: ['unit'],
        },
      },
      executor
    );

    const response = await registry.execute('get_weather', {unit: 'kelvin'});

    expect({result: response.result, executorCalls: callCount(executor)}).toEqual({
      result: expect.stringMatching(/\/unit.*(?:allowed values|equal)/i),
      executorCalls: 0,
    });
  });

  it('normalizes legacy Ajv dotted paths to JSON Pointer paths for enum failures', async () => {
    const registry = new ToolRegistry();
    const executor = weatherExecutor();
    registry.register(
      {
        name: 'get_weather',
        description: 'Gets weather for a location',
        inputSchema: {
          type: 'object',
          properties: {
            forecast: {
              type: 'object',
              properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}},
              required: ['unit'],
            },
          },
          required: ['forecast'],
        },
      },
      executor
    );

    const response = await registry.execute('get_weather', {forecast: {unit: 'kelvin'}});

    expect({result: response.result, executorCalls: callCount(executor)}).toEqual({
      result: 'Invalid tool input: /forecast/unit must be equal to one of the allowed values.',
      executorCalls: 0,
    });
  });

  it('caches a function source validator by returned schema object', async () => {
    const schema = {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      () => ({name: 'get_weather', description: 'Gets weather for a location', inputSchema: schema}),
      async () => 'sunny'
    );

    await registry.execute('get_weather', {location: 'Paris'});
    await registry.execute('get_weather', {location: 'Berlin'});

    expect(compile).toHaveBeenCalledTimes(1);
    compile.mockRestore();
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the full missing property path as required and never invokes the executor ([validated by rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16), [validated by returns a rejection for missing required input without calling the executor](../../src/orchestration/tools/registry.test.ts#L49), [validated by names the full path for a nested missing required input field](../../src/orchestration/tools/registry.test.ts#L62)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46), [validated by names the full path for a nested wrong-typed input field](../../src/orchestration/tools/registry.test.ts#L75), [validated by names the path and expected type for wrong-typed input without leaking its value](../../src/orchestration/tools/registry.test.ts#L88), [validated by normalizes Ajv should-be wording for a rejected input type](../../src/orchestration/tools/registry.test.ts#L106)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults; an enum rejection names the failing property path and enum constraint in JSON Pointer form ([validated by names the path and enum constraint for an input outside the declared enum](../../src/orchestration/tools/registry.test.ts#L120), [validated by normalizes legacy Ajv dotted paths to JSON Pointer paths for enum failures](../../src/orchestration/tools/registry.test.ts#L144)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by caches a function source validator by returned schema object](../../src/orchestration/tools/registry.test.ts#L160)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
